  feedback = _text(py.M.get(payload, "feedback", ""), "绘图反馈", 20000);
  result = py.call(compile_result, [py.M.get(payload, "spec"), settings], {"description": description, "feedback": feedback, "figure_id": _text(py.M.get(payload, "figure_id", ""), "视图 ID", 80)});
